# Testando Componentes React com Vitest e Testing Library

Guia prático para configurar e escrever testes robustos para componentes React usando Vitest.

## 1. Configuração Inicial

```bash
# Instalar dependências de teste
npm install -D vitest @vitest/ui @testing-library/react @testing-library/jest-dom @testing-library/user-event jsdom
```

**vite.config.ts**
```typescript
/// <reference types="vitest" />
import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'

export default defineConfig({
  plugins: [react()],
  test: {
    globals: true,
    environment: 'jsdom',
    setupFiles: ['./src/test-setup.ts'],
    css: true,
  },
})
```

**src/test-setup.ts**
```typescript
import '@testing-library/jest-dom'

// Mock de APIs globais
Object.defineProperty(window, 'matchMedia', {
  writable: true,
  value: vi.fn().mockImplementation(query => ({
    matches: false,
    media: query,
    onchange: null,
    addListener: vi.fn(), // deprecated
    removeListener: vi.fn(), // deprecated
    addEventListener: vi.fn(),
    removeEventListener: vi.fn(),
    dispatchEvent: vi.fn(),
  })),
})

// Mock do IntersectionObserver
global.IntersectionObserver = vi.fn().mockImplementation(() => ({
  observe: vi.fn(),
  unobserve: vi.fn(),
  disconnect: vi.fn(),
}))
```

## 2. Testando Componentes Básicos

**Button.test.tsx**
```typescript
import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { Button } from './Button'

describe('Button Component', () => {
  test('renders with correct text', () => {
    render(<Button>Click me</Button>)
    expect(screen.getByRole('button', { name: /click me/i })).toBeInTheDocument()
  })

  test('handles click events', async () => {
    const user = userEvent.setup()
    const handleClick = vi.fn()

    render(<Button onClick={handleClick}>Click me</Button>)

    await user.click(screen.getByRole('button'))
    expect(handleClick).toHaveBeenCalledTimes(1)
  })

  test('disables when loading', () => {
    render(<Button loading>Loading...</Button>)
    expect(screen.getByRole('button')).toBeDisabled()
  })

  test('shows loading spinner when loading', () => {
    render(<Button loading>Loading...</Button>)
    expect(screen.getByRole('button')).toHaveClass('opacity-50')
    // Ou testar pela presença do spinner SVG
    expect(screen.getByTestId('loading-spinner')).toBeInTheDocument()
  })

  test('applies correct variant classes', () => {
    const { rerender } = render(<Button variant="primary">Primary</Button>)
    expect(screen.getByRole('button')).toHaveClass('bg-primary-600')

    rerender(<Button variant="secondary">Secondary</Button>)
    expect(screen.getByRole('button')).toHaveClass('bg-gray-100')
  })
})
```

## 3. Testando Hooks Customizados

**useCounter.test.ts**
```typescript
import { renderHook, act } from '@testing-library/react'
import { useCounter } from './useCounter'

describe('useCounter Hook', () => {
  test('initializes with default value', () => {
    const { result } = renderHook(() => useCounter())
    expect(result.current.count).toBe(0)
  })

  test('initializes with custom value', () => {
    const { result } = renderHook(() => useCounter(10))
    expect(result.current.count).toBe(10)
  })

  test('increments count', () => {
    const { result } = renderHook(() => useCounter())

    act(() => {
      result.current.increment()
    })

    expect(result.current.count).toBe(1)
  })

  test('decrements count', () => {
    const { result } = renderHook(() => useCounter(5))

    act(() => {
      result.current.decrement()
    })

    expect(result.current.count).toBe(4)
  })

  test('resets count', () => {
    const { result } = renderHook(() => useCounter(10))

    act(() => {
      result.current.increment()
      result.current.reset()
    })

    expect(result.current.count).toBe(10)
  })
})
```

## 4. Testando com Context

**ThemeProvider.test.tsx**
```typescript
import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { ThemeProvider, useTheme } from './ThemeProvider'

const ThemeConsumer = () => {
  const { theme, toggleTheme } = useTheme()
  return (
    <div>
      <span data-testid="current-theme">{theme}</span>
      <button onClick={toggleTheme}>Toggle Theme</button>
    </div>
  )
}

const renderWithTheme = (initialTheme = 'light') => {
  return render(
    <ThemeProvider initialTheme={initialTheme}>
      <ThemeConsumer />
    </ThemeProvider>
  )
}

describe('ThemeProvider', () => {
  test('provides default theme', () => {
    renderWithTheme()
    expect(screen.getByTestId('current-theme')).toHaveTextContent('light')
  })

  test('toggles theme', async () => {
    const user = userEvent.setup()
    renderWithTheme()

    await user.click(screen.getByText('Toggle Theme'))
    expect(screen.getByTestId('current-theme')).toHaveTextContent('dark')

    await user.click(screen.getByText('Toggle Theme'))
    expect(screen.getByTestId('current-theme')).toHaveTextContent('light')
  })

  test('initializes with custom theme', () => {
    renderWithTheme('dark')
    expect(screen.getByTestId('current-theme')).toHaveTextContent('dark')
  })
})
```

## 5. Testando Requisições HTTP

**UserProfile.test.tsx**
```typescript
import { render, screen, waitFor } from '@testing-library/react'
import { rest } from 'msw'
import { setupServer } from 'msw/node'
import { UserProfile } from './UserProfile'

const server = setupServer(
  rest.get('/api/users/:id', (req, res, ctx) => {
    const { id } = req.params

    if (id === '1') {
      return res(
        ctx.json({
          id: '1',
          name: 'John Doe',
          email: 'john@example.com'
        })
      )
    }

    return res(ctx.status(404))
  })
)

beforeAll(() => server.listen())
afterEach(() => server.resetHandlers())
afterAll(() => server.close())

describe('UserProfile Component', () => {
  test('displays user information when loaded successfully', async () => {
    render(<UserProfile userId="1" />)

    expect(screen.getByText('Carregando...')).toBeInTheDocument()

    await waitFor(() => {
      expect(screen.getByText('John Doe')).toBeInTheDocument()
    })

    expect(screen.getByText('john@example.com')).toBeInTheDocument()
    expect(screen.queryByText('Carregando...')).not.toBeInTheDocument()
  })

  test('displays error message when user not found', async () => {
    render(<UserProfile userId="999" />)

    await waitFor(() => {
      expect(screen.getByText('Usuário não encontrado')).toBeInTheDocument()
    })
  })

  test('handles network errors', async () => {
    server.use(
      rest.get('/api/users/:id', (req, res, ctx) => {
        return res.networkError('Falha na conexão')
      })
    )

    render(<UserProfile userId="1" />)

    await waitFor(() => {
      expect(screen.getByText('Erro ao carregar usuário')).toBeInTheDocument()
    })
  })
})
```

## 6. Testando Formulários

**ContactForm.test.tsx**
```typescript
import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { ContactForm } from './ContactForm'

describe('ContactForm', () => {
  test('submits form with valid data', async () => {
    const user = userEvent.setup()
    const mockSubmit = vi.fn()

    render(<ContactForm onSubmit={mockSubmit} />)

    await user.type(screen.getByLabelText(/nome/i), 'João Silva')
    await user.type(screen.getByLabelText(/email/i), 'joao@example.com')
    await user.type(screen.getByLabelText(/mensagem/i), 'Olá, gostaria de mais informações.')

    await user.click(screen.getByRole('button', { name: /enviar/i }))

    expect(mockSubmit).toHaveBeenCalledWith({
      nome: 'João Silva',
      email: 'joao@example.com',
      mensagem: 'Olá, gostaria de mais informações.'
    })
  })

  test('shows validation errors for invalid data', async () => {
    const user = userEvent.setup()

    render(<ContactForm onSubmit={vi.fn()} />)

    // Tentar enviar formulário vazio
    await user.click(screen.getByRole('button', { name: /enviar/i }))

    expect(screen.getByText('Nome é obrigatório')).toBeInTheDocument()
    expect(screen.getByText('Email é obrigatório')).toBeInTheDocument()
  })

  test('validates email format', async () => {
    const user = userEvent.setup()

    render(<ContactForm onSubmit={vi.fn()} />)

    await user.type(screen.getByLabelText(/email/i), 'email-inválido')
    await user.click(screen.getByRole('button', { name: /enviar/i }))

    expect(screen.getByText('Email deve ter um formato válido')).toBeInTheDocument()
  })

  test('disables submit button while submitting', async () => {
    const user = userEvent.setup()
    const slowSubmit = () => new Promise(resolve => setTimeout(resolve, 100))

    render(<ContactForm onSubmit={slowSubmit} />)

    await user.type(screen.getByLabelText(/nome/i), 'João')
    await user.type(screen.getByLabelText(/email/i), 'joao@example.com')

    const submitButton = screen.getByRole('button', { name: /enviar/i })
    await user.click(submitButton)

    expect(submitButton).toBeDisabled()
    expect(screen.getByText(/enviando/i)).toBeInTheDocument()
  })
})
```

## 7. Utilitários de Teste

**test-utils.tsx**
```typescript
import { ReactElement } from 'react'
import { render, RenderOptions } from '@testing-library/react'
import { ThemeProvider } from '../contexts/ThemeProvider'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'

const AllTheProviders = ({ children }: { children: React.ReactNode }) => {
  const queryClient = new QueryClient({
    defaultOptions: {
      queries: {
        retry: false,
      },
    },
  })

  return (
    <QueryClientProvider client={queryClient}>
      <ThemeProvider>
        {children}
      </ThemeProvider>
    </QueryClientProvider>
  )
}

const customRender = (
  ui: ReactElement,
  options?: Omit<RenderOptions, 'wrapper'>,
) => render(ui, { wrapper: AllTheProviders, ...options })

export * from '@testing-library/react'
export { customRender as render }
```

## 8. Scripts do Package.json

```json
{
  "scripts": {
    "test": "vitest",
    "test:ui": "vitest --ui",
    "test:run": "vitest run",
    "test:coverage": "vitest run --coverage",
    "test:watch": "vitest --watch"
  }
}
```

## Boas Práticas

1. **AAA Pattern**: Arrange, Act, Assert
2. **Testar comportamento, não implementação**
3. **Usar queries semânticas** (`getByRole`, `getByLabelText`)
4. **Preferir `userEvent` ao `fireEvent`**
5. **Mockar apenas o necessário**
6. **Escrever testes legíveis e descritivos**
7. **Usar `data-testid` como último recurso**

Com essa configuração, você terá uma base sólida para testar aplicações React de forma eficiente!

