import { useEffect, useState } from 'react'
import { getCLS, getFID, getFCP, getLCP, getTTFB } from 'web-vitals'

interface Metric {
  name: string
  value: number
  rating: 'good' | 'needs-improvement' | 'poor'
}

export const MetricsDashboard = () => {
  const [metrics, setMetrics] = useState<Metric[]>([])

  useEffect(() => {
    const updateMetric = (metric: any) => {
      setMetrics(prev => {
        const existing = prev.find(m => m.name === metric.name)
        if (existing) {
          return prev.map(m => m.name === metric.name ? {
            name: metric.name,
            value: metric.value,
            rating: metric.rating
          } : m)
        }
        return [...prev, {
          name: metric.name,
          value: metric.value,
          rating: metric.rating
        }]
      })
    }

    getCLS(updateMetric)
    getFID(updateMetric)
    getFCP(updateMetric)
    getLCP(updateMetric)
    getTTFB(updateMetric)
  }, [])

  const getRatingColor = (rating: string) => {
    switch (rating) {
      case 'good': return 'text-green-600'
      case 'needs-improvement': return 'text-yellow-600'
      case 'poor': return 'text-red-600'
      default: return 'text-gray-600'
    }
  }

  if (process.env.NODE_ENV !== 'development') {
    return null
  }

  return (
    <div className="fixed bottom-4 right-4 bg-white border border-gray-200 rounded-lg p-4 shadow-lg">
      <h3 className="font-bold mb-2">Web Vitals</h3>
      {metrics.map(metric => (
        <div key={metric.name} className="flex justify-between items-center mb-1">
          <span className="text-sm font-medium">{metric.name}:</span>
          <span className={`text-sm ${getRatingColor(metric.rating)}`}>
            {Math.round(metric.value)}
          </span>
        </div>
      ))}
    </div>
  )
}
