import * as Sentry from '@sentry/react'

export const trackPerformance = {
  // Track component loading time
  componentLoad: (componentName: string) => {
    const transaction = Sentry.startTransaction({
      name: `Component Load: ${componentName}`,
      op: 'navigation'
    })

    return {
      finish: () => transaction.finish()
    }
  },

  // Track async operations
  asyncOperation: (operationName: string) => {
    const transaction = Sentry.startTransaction({
      name: operationName,
      op: 'async'
    })

    return {
      setTag: (key: string, value: string) => transaction.setTag(key, value),
      setData: (key: string, value: any) => transaction.setData(key, value),
      finish: () => transaction.finish()
    }
  },

  // Track Core Web Vitals
  webVitals: () => {
    import('web-vitals').then(({ getCLS, getFID, getFCP, getLCP, getTTFB }) => {
      getCLS((metric) => {
        Sentry.addBreadcrumb({
          category: 'web-vitals',
          message: `CLS: ${metric.value}`,
          level: 'info',
          data: metric
        })
      })

      getFID((metric) => {
        Sentry.addBreadcrumb({
          category: 'web-vitals',
          message: `FID: ${metric.value}`,
          level: 'info',
          data: metric
        })
