## 4. Analytics Hook

**hooks/useAnalytics.ts**
```typescript
import { useEffect, useCallback } from 'react'
import * as Sentry from '@sentry/react'
import { useRouter } from 'next/router'

interface AnalyticsEvent {
  action: string
  category: string
  label?: string
  value?: number
  properties?: Record<string, any>
}

export const useAnalytics = () => {
  const router = useRouter()

  // Track route changes
  useEffect(() => {
    const handleRouteChange = (url: string) => {
      // Google Analytics
      if (typeof window !== 'undefined' && window.gtag) {
        window.gtag('config', process.env.NEXT_PUBLIC_GA_ID!, {
          page_path: url,
        })
      }

      // Sentry
      Sentry.addBreadcrumb({
        category: 'navigation',
        message: `Navigated to ${url}`,
        level: 'info'
      })
    }

    router.events.on('routeChangeComplete', handleRouteChange)
    return () => router.events.off('routeChangeComplete', handleRouteChange)
  }, [router])

  const track = useCallback((event: AnalyticsEvent) => {
    // Google Analytics
    if (typeof window !== 'undefined' && window.gtag) {
      window.gtag('event', event.action, {
        event_category: event.category,
        event_label: event.label,
        value: event.value,
        custom_parameters: event.properties
      })
    }

    // Sentry
    Sentry.addBreadcrumb({
      category: 'user-action',
      message: `${event.category}: ${event.action}`,
      level: 'info',
      data: {
        label: event.label,
        value: event.value,
        ...event.properties
      }
    })

    // Console for development
    if (process.env.NODE_ENV === 'development') {
      console.log('Analytics Event:', event)
    }
  }, [])

  const trackError = useCallback((error: Error, context?: Record<string, any>) => {
    Sentry.captureException(error, {
      tags: {
        section: 'user-action'
      },
      extra: context
    })
  }, [])

  const setUser = useCallback((userId: string, properties?: Record<string, any>) => {
    Sentry.setUser({
      id: userId,
      ...properties
    })

    if (typeof window !== 'undefined' && window.gtag) {
      window.gtag('config', process.env.NEXT_PUBLIC_GA_ID!, {
        user_id: userId,
        custom_map: properties
      })
    }
  }, [])

  return {
    track,
    trackError,
    setUser
  }
}
```

## 5. API Monitoring

**lib/api-monitor.ts**
```typescript
import * as Sentry from '@sentry/react'

interface APICallOptions {
  url: string
  method: string
  body?: any
  headers?: Record<string, string>
}

export const monitoredFetch = async (options: APICallOptions) => {
  const transaction = Sentry.startTransaction({
    name: `API ${options.method} ${options.url}`,
    op: 'http.client'
  })

  transaction.setData('url', options.url)
  transaction.setData('method', options.method)

  const startTime = performance.now()

  try {
    const response = await fetch(options.url, {
      method: options.method,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers
      },
      body: options.body ? JSON.stringify(options.body) : undefined
    })

    const duration = performance.now() - startTime

    transaction.setTag('http.status_code', response.status.toString())
    transaction.setData('duration', duration)

    if (!response.ok) {
      transaction.setTag('error', 'true')

      const errorData = await response.text()
      Sentry.captureException(new Error(`API Error: ${response.status}`), {
        tags: {
          api_url: options.url,
          api_method: options.method,
          status_code: response.status
        },
        extra: {
          response_data: errorData,
          request_data: options.body
        }
      })
    }

    return response

  } catch (error) {
    transaction.setTag('error', 'true')

    Sentry.captureException(error, {
      tags: {
        api_url: options.url,
        api_method: options.method
      },
      extra: {
        request_data: options.body
      }
    })

    throw error

  } finally {
    transaction.finish()
  }
}
```

## 6. Component Monitoring

**hoc/withMonitoring.tsx**
```typescript
import { Component, ComponentType } from 'react'
import * as Sentry from '@sentry/react'
import { trackPerformance } from '@/lib/performance'

interface MonitoringState {
  hasError: boolean
  renderTime?: number
}

export function withMonitoring<P extends object>(
  WrappedComponent: ComponentType<P>,
  componentName?: string
) {
  return class extends Component<P, MonitoringState> {
    private renderStart = 0
    private transaction: any

    constructor(props: P) {
      super(props)
      this.state = { hasError: false }

      const name = componentName || WrappedComponent.displayName || WrappedComponent.name
      this.transaction = trackPerformance.componentLoad(name)
    }

    componentDidMount() {
      this.transaction.finish()

      const renderTime = performance.now() - this.renderStart
      this.setState({ renderTime })

      Sentry.addBreadcrumb({
        category: 'component',
        message: `${componentName} mounted in ${renderTime}ms`,
        level: 'info'
      })
    }

    componentDidCatch(error: Error, errorInfo: any) {
      this.setState({ hasError: true })

      Sentry.captureException(error, {
        tags: {
          component: componentName || 'Unknown'
        },
        extra: errorInfo
      })
    }

    render() {
      this.renderStart = performance.now()

      if (this.state.hasError) {
        return (
          <div className="p-4 bg-red-50 border border-red-200 rounded">
            <p className="text-red-800">Error in component {componentName}</p>
          </div>
        )
      }

      return <WrappedComponent {...this.props} />
    }
  }
}
